  ('long-island-bahamas', '11C', 'Long Island', 'Bahamas', 'The deepest breath-hold on Earth', 'live', 'verified', 'tropicalBeach', 'Bahamas', '{"tropical","expedition","diveglobal","wildlife","culture","romance"}', '{"tropical"}', '{"premier","ultra"}', null, null, '{"key_facts":["~80 mi long, split by the Tropic of Cancer, ~165 mi SE of Nassau","Two airports: Stella Maris (SML) + Deadman''s Cay (LGI); ~1h from Nassau","Dean''s Blue Hole: 663 ft - deepest freediving-accessible hole, a global mecca (Vertical Blue)","Cape Santa Maria + Stella Maris resorts; Cape Santa Maria Beach world-ranked","Depth ranking varies (frame ''one of the deepest''); malaria none; hurricane Jun-Nov peak Aug-Oct"],"safety":{"emergency":"911 / 919","hospital":"clinics only; Nassau referral","malaria":"NONE","yellow_fever":"only if arriving from an endemic country","hurricane":"Jun-Nov, peak Aug-Oct","dive_no_fly":"18-24h (DAN); freediving = extreme/technical, safety divers required","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-09-01T16:20:19Z","page_updated":"2026-05-28T17:01:45+01:00","source_country":"bahamas","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":null,"jewels":[{"name":"Vertical Blue Freediving School","blurb":"\"The world''s premier freediving school, at the world''s most beautiful blue hole\" - Dean''s Blue Hole, given as 203 metres; established 2006, \"75 World records set\". 2027 courses published: Beginner/AIDA 2 Star (4 days, $715), Intermediate/AIDA 3 Star (5 days, $845), No Fins (4 days, $920), Training Camp (6 days, $970), AIDA Instructor (7 days, $1,530); a deposit secures a place. Carried from the earlier dossier''s \"Dean''s Blue Hole freedive\" jewel (deansbluehole.com, 2026-07-02), now attached to the school that runs the courses.","si":["expedition","diveglobal","adventure","sports"],"commission":"operator","wells":["activities","stay"],"draw_rank":2,"fit_rules":{"duration":"4 to 7 days per course (verticalblue.net)","before":"none stated for the Beginner/AIDA 2 Star course","after":"not stated on the page","pairs_with":"Dean''s Blue Hole","time_season":"2027 dates published: Beginner Feb 25-28 and Apr 22-25; Intermediate Mar 3-7 and May 12-16; Training Camp Mar 25-31; Instructor Apr 1-8"},"tier_absent_reason":"does-not-compete","source":"https://www.verticalblue.net/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Dean''s Blue Hole","blurb":"\"663 feet depths of the third deepest blue hole in the world\", \"enclosed on three sides by a natural rock amphitheater, and on the fourth side by a turquoise lagoon and powdery white beach\". Visitors can \"climb up the rocky pathway and plunge into\" it, and the \"Vertical Blue Free Diving Competition is held every year\". Carried from the earlier dossier''s \"Dean''s Blue Hole snorkel/beach\" jewel and re-read today; the old \"sheltered cove\" wording is replaced by the Ministry''s.","si":["tropical","diveglobal","expedition","adventure"],"wells":["activities"],"draw_rank":1,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/natural-wonders/deans-blue-hole","accessed":"2026-10-03","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Stella Maris diving - Conception Island wall and the Comberbach wreck","blurb":"Conception Island''s \"1.5 mile-long leeside coral wall, with tops of only 45 feet\"; the M.V. Comberbach, a steel freighter \"sunk there about four decades ago, prepared for diving\"; leeside reefs \"within 30 minutes by boat\" at 30-60 feet. \"Scuba Diving is being offered by a variety of local operators that go out with 1-4 persons\" and the resort is \"glad to provide assistance.\" Carried from the earlier \"Stella Maris reef & wall dive\" jewel: what changed is that the page now says local operators run the dives, not a resort dive shop.","si":["diveglobal","ocean","adventure"],"commission":"operator","wells":["activities","move","stay"],"draw_rank":5,"tier_absent_reason":"does-not-compete","source":"https://www.stellamarisresort.com/scuba-diving/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Cape Santa Maria Beach Resort","blurb":"\"Romantic bungalows to spacious two-bedroom villas\" on \"miles of talcum-powder sand and swaying palms\"; one- and two-bedroom Beachfront Bungalows and Beachfront Villas. Activities include \"fishing, cave snorkelling, sailing, cycling, kayaking, and stand-up paddle boarding\" and Hobie Cats on Calabash Bay. \"The resort is closed in September and October.\"","si":["romance","tropical","family","sailing"],"commission":"hotel","wells":["activities","move","stay"],"draw_rank":3,"tier_absent_reason":"not-established","source":"https://www.capesantamaria.com/long-island-bahamas-resort","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Stella Maris Resort Club & Marina","blurb":"\"An intimate out island style resort\" with hotel rooms, cottages and apartments, three- and four-bedroom homes, a marina and its own air service. 2026 rates published: hotel room apartment $190-$290, 1-bedroom cottage $240-$330, 3- and 4-bedroom homes $660-$800 a night, plus 10% VAT, a 6% resort levy (+10% VAT), a $6 maid service charge and an energy surcharge. SML airport is \"approximately half-mile from resort\".","si":["tropical","diveglobal","family"],"commission":"hotel","wells":["fly","stay"],"draw_rank":4,"tier_absent_reason":"not-established","source":"https://www.stellamarisresort.com/rates/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bonafide Bonefishing","blurb":"James \"Docky\" Smith \"is an independent, certified Bahamas Fly Fishing Guide, and native of north Long Island, with over thirty years of professional guiding experience.\" Fly and spin fishing for bonefish, tarpon and permit, reef and offshore trips, and eco trips to Sandy Cay, Columbus Harbor and \"Da Farm\". Stella Maris Resort publishes bonefishing on a 17'' Maverick at $600 full day and $550 half day, max 2 guests plus guide, with Bonafide''s guides.","si":["ocean","adventure","tropical","sports"],"commission":"guide","wells":["activities","stay"],"draw_rank":6,"tier_absent_reason":"does-not-compete","source":"https://www.bonafidebonefishing.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Stella Maris deep-sea and reef fishing","blurb":"Deep sea for \"Blue & White Marlin, Sailfish, Wahoo, Rainbow Runners, Yellow & Black Fin Tuna, and Mahi-Mahi\" on a 31 Contender with 2-man crew, $1,200/day (8am-3pm); reef fishing lee-side and Atlantic side, 32 ft boat up to 6 people $950/day plus 10% VAT, smaller boats about $450/day.","si":["ocean","adventure","sports"],"commission":"operator","wells":["activities","move"],"draw_rank":7,"tier_absent_reason":"does-not-compete","source":"https://www.stellamarisresort.com/fishing/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Conception Island National Park","blurb":"\"30,000 acre Conception Island national park\", \"Established in 1978\", \"Only accessible by boat\". \"Long tail tropic birds, sooty terns, oyster catchers, and ospreys nest on the island\" and \"Green turtles forage in the creek, off the southwestern shore, and in the northern bay\". A \"speed limit of 4 knots inside the creek\"; \"3 moorings installed in this national park for larger boats\".","si":["wildlife","diveglobal","sailing","expedition"],"wells":["activities","eat","move"],"draw_rank":8,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/conception-island-national-park/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Hamilton''s Cave","blurb":"\"the largest cave system in the Bahamas. The Lucayan Indians were thought to have lived here around 500 A.D., and many Lucayan artifacts were discovered in 1936.\" \"owned and operated by Mr. Leonard Cartwright, a Long Island native who offers tours through the cave system, with some passages over 15 meters wide and 3 meters high\". \"Tours are $20/adult and can be booked through our front office\" (Cape Santa Maria''s printed guide).","si":["culture","adventure","family"],"commission":"guide","wells":["activities"],"draw_rank":9,"tier_absent_reason":"does-not-compete","source":"https://www.mmopa.com/assets/2026BahamasFlyOut/Cape-Santa-Maria_Map_Cape-Long-Island-Guide.pdf","accessed":"2026-10-03"},{"name":"Columbus Monument, Columbus Point","blurb":"\"constructed by the Long Islanders Association as a tribute to the arrival of Christopher Columbus on October 17th, 1492\", \"perched atop the white cliffs of the Long Island coastline\"; \"a road constructed in 2019\" made it a cycling destination from Cape Santa Maria (\"11.5 km, 7.5 miles round-trip\"), with \"picnic areas, amazing snorkeling, private beaches, a natural ''lazy river''\". The Ministry names the Columbus Point monument marking Columbus''s landfall.","si":["culture","tropical","hiking"],"wells":["activities"],"draw_rank":10,"tier_absent_reason":"not-sold","source":"https://www.mmopa.com/assets/2026BahamasFlyOut/Cape-Santa-Maria_Map_Cape-Long-Island-Guide.pdf","accessed":"2026-10-03","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"The twin churches of Clarence Town - St. Paul''s and St. Peter & St. Paul''s","blurb":"The Ministry names \"St. Paul''s Church and St. Peter & St. Paul''s Church\" in Clarence Town, designed by Father Jerome Hawes. Cape Santa Maria''s guide: \"both designed by architect and priest John Hawes\" with \"similarly striking recognizable twin towers\"; St. Paul''s is Anglican, St. Peter and Paul Roman Catholic.","si":["culture","pilgrimage"],"wells":["activities"],"draw_rank":11,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/long-island","accessed":"2026-10-03","commission":"entry (site ticket, non-commissionable) - guide (licensed local guide) sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a religious or heritage site - the entry is non-commissionable; a guided visit is the paid route"},{"name":"Long Island Regatta, Salt Pond","blurb":"\"the second largest in The Bahamas, next to the National Family Island Regatta held in The Exumas, and it is the major fund-raiser on the island.\" Sloops race in A, B and C class for cash prizes and trophies, with local food and island bands. 2025 edition: June 4-7, 2025, Cultural Site, Salt Pond. Contact Mr. Chester Fox, (242) 338-0038 or (242) 357-1292. The 53rd edition ran June 1-4, 2022 (sailingscuttlebutt.com).","si":["sailing","spectator","culture","family"],"wells":["activities","eat","move"],"draw_rank":12,"tier_absent_reason":"not-sold","source":"https://tourismtoday.com/events/long-island-regatta","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"event (free to attend) - pair with Stay-Well and an event-week package","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a festival or regatta - free to attend; the stay and the package around it are the paid route"},{"name":"Cape Santa Maria Beach","blurb":"Named by the Ministry of Tourism among Long Island''s sights; Cape Santa Maria Resort describes \"miles of talcum-powder sand and swaying palms\" on the shore it fronts.","si":["tropical","romance","family"],"wells":["activities","stay"],"draw_rank":13,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/long-island","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"entry non-commissionable (curated) - pair with a beach stay or boat day","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a beach - free; the stay and a boat day are the paid route"},{"name":"Sandy Cay Iguana Tour","blurb":"\"5 hour excursion | 9 a.m. to 2 p.m.\" that \"takes you to the natural habitat of Sandy Cay''s rare rock iguanas on one of the most breathtaking sandbars\". Cape Santa Maria also runs a 3-hour snorkelling and nature cruise that \"includes snorkel gear and an experienced, certified tour guide\".","si":["wildlife","tropical","family"],"commission":"hotel","wells":["activities","gear","move"],"draw_rank":14,"fit_rules":{"duration":"5 hours, 9 a.m. to 2 p.m. (capesantamaria.com/activities)","before":"none stated","after":"none stated","pairs_with":"Cape Santa Maria Beach","time_season":"the resort is closed in September and October"},"tier_absent_reason":"does-not-compete","source":"https://www.capesantamaria.com/activities","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Capt. Delbert Smith - diving, fishing and sightseeing","blurb":"\"a Long Island native and one of the best island guides\", providing \"fishing, diving, and snorkeling services from the North end of Long Island\". His page lists diving and snorkelling at \"Shark Reef, Barracuda Heads, and Blue Tang Reef\", deep-sea and flats bonefishing, sightseeing, the North End Caves and the Cape Santa Maria flats. Cape Santa Maria''s one- and two-tank dives are led by \"PADI Certified Dive Master, Delbert Smith\".","si":["diveglobal","ocean","adventure"],"commission":"guide","wells":["activities"],"draw_rank":15,"tier_absent_reason":"does-not-compete","source":"https://www.deansbluehole.com/delbertsmith","accessed":"2026-10-03"},{"name":"Seaside Village Eco Tours and the Deadman''s Cay swimming pigs","blurb":"From the Seaside Village dock in Deadman''s Cay, \"a spectacular 30min boat ride through the flats with stops along the way to some of the island''s most spectacular beaches and sandbars and a visit with local swimming pigs.\" \"Pre-Booking required with the Cape Front Office team.\" (Cape Santa Maria''s printed guide.)","si":["wildlife","tropical","family"],"commission":"guide","wells":["activities","move","stay"],"draw_rank":16,"tier_absent_reason":"does-not-compete","source":"https://www.mmopa.com/assets/2026BahamasFlyOut/Cape-Santa-Maria_Map_Cape-Long-Island-Guide.pdf","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Max''s Conch Bar & Grill","blurb":"\"This roadside conch shack is perhaps the most famous of all Long Island institutions. The quality of the local cuisine, the strength of their rum punch, and the character of the local patrons make this a must visit on any (and every) Long Island road-trip.\" Run by \"Gary, Liz and Karnetha and the team\"; \"Look for the international array of flags along the roadside\". Phone +1 242 337 0056 and Deadman''s Cay location per au.trip.com.","si":["culinary","culture"],"wells":["activities","eat"],"draw_rank":17,"tier_absent_reason":"does-not-compete","source":"https://www.mmopa.com/assets/2026BahamasFlyOut/Cape-Santa-Maria_Map_Cape-Long-Island-Guide.pdf","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"venue (restaurant, direct) - pair with an Eat-Well reservation or food tour","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a restaurant or bar - booked direct; the Eat-Well lane carries the paid version"},{"name":"Docky''s Flats Bar","blurb":"\"Eat local Bahamian fare in a friendly and open air, casual bar/restaurant setting\" - \"freshly caught fish, lobster and all the different conch dishes, cooked island style\" and rum cocktails. Open \"on Wednesdays, Fridays and Saturdays after fishing hours\"; \"Please reserve your dinner ahead of time by calling in\".","si":["culinary","tropical"],"wells":["activities","eat"],"draw_rank":18,"tier_absent_reason":"does-not-compete","source":"https://www.bonafidebonefishing.com/dockys-flats-bar","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"venue (restaurant, direct) - pair with an Eat-Well reservation or food tour","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a restaurant or bar - booked direct; the Eat-Well lane carries the paid version"},{"name":"Kenny''s Conch Shack, Seaside Village","blurb":"\"Kenny''s Conch Shack is located right on the Seaside Village dock where Kenny serves up one of the very best Conch Salads in the Bahamas.\" (Cape Santa Maria''s printed guide.)","si":["culinary","culture"],"wells":["activities","eat","stay"],"draw_rank":19,"tier_absent_reason":"does-not-compete","source":"https://www.mmopa.com/assets/2026BahamasFlyOut/Cape-Santa-Maria_Map_Cape-Long-Island-Guide.pdf","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)","commission":"venue (restaurant, direct) - pair with an Eat-Well reservation or food tour","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a restaurant or bar - booked direct; the Eat-Well lane carries the paid version"},{"name":"Adderley''s Plantation","blurb":"\"One of the original Loyalist settlements on Long Island. This cotton plantation was granted to Mr. Abraham Adderley in 1790. The original grant of 700 acres expanded to 2500 acres in 1820\". \"The trail up to the plantation is lined with shrubs and trees labelled with their common and Latin names and their various uses in the practise of Bahamian ''Bush Medicine''.\"","si":["culture","hiking"],"wells":["activities"],"draw_rank":20,"tier_absent_reason":"not-sold","source":"https://www.mmopa.com/assets/2026BahamasFlyOut/Cape-Santa-Maria_Map_Cape-Long-Island-Guide.pdf","accessed":"2026-10-03","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"St. Mary the Blessed Virgin ruin and the Shrimp Hole","blurb":"\"the spectacular ruin of what may be the oldest church in all of the Bahamas (St. Mary the Blessed Virgin est. 1799)\"; behind it, a \"relatively simple 10min hike\" leads to \"a freshwater limestone cave inhabited by what are thought to be small red Sterrar''s Cave Shrimp\".","si":["culture","hiking","wildlife","pilgrimage"],"wells":["activities"],"draw_rank":21,"tier_absent_reason":"not-sold","source":"https://www.mmopa.com/assets/2026BahamasFlyOut/Cape-Santa-Maria_Map_Cape-Long-Island-Guide.pdf","accessed":"2026-10-03","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Starfish Traders","blurb":"\"local artisans create everything from purses to beach bags, and iPad cases to oven-mitts\", incorporating \"local straw work with bright fabrics\"; \"Their shop is open at 10am MTF and features a boutique to purchase their crafts, plus a sewing and cutting room\".","si":["culture"],"wells":["activities","shop","stay"],"draw_rank":22,"tier_absent_reason":"does-not-compete","source":"https://www.mmopa.com/assets/2026BahamasFlyOut/Cape-Santa-Maria_Map_Cape-Long-Island-Guide.pdf","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"venue (retail) - non-commissionable; a guided town or shopping tour sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a market, shop or gallery - free to visit; a guided tour is the paid route"},{"name":"Sheep Runner ferry","blurb":"Long Island to George Town, Exuma \"Mondays, Wednesdays & Fridays\": departs Long Island 7:30 am, arrives George Town 9:00 am; returns 3:00 pm, arriving 4:30 pm. Adult one way $110, child $71, infants under 2 free, same-day round trip from Long Island $165, VAT included. \"in inclement weather, the Captain may choose to dock at Harry Cay\".","si":["ocean","tropical"],"commission":"operator","wells":["activities","move"],"draw_rank":23,"tier_absent_reason":"does-not-compete","source":"https://www.sheeprunner.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Long Island Harbour Club","blurb":"8 rooms - \"elegant Club Rooms or ... casual ... Beach Shacks\" - steps from the Sheep Runner dock at Salt Pond, with private charters for up to 20 passengers \"starting at just $1980 including VAT\".","si":["tropical","sailing"],"commission":"hotel","wells":["activities","stay"],"draw_rank":24,"tier_absent_reason":"not-established","source":"https://www.sheeprunner.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bonafide Cottage","blurb":"Two bedrooms for up to 4 guests overlooking Seymours, Horizon Bay and Cape Santa Maria Beach. $250 nightly, $1,600 weekly; a 5-night bonefishing package with 3 days guided fishing is $4,025, including a rental car.","si":["ocean","tropical","adventure"],"commission":"guide","wells":["activities","gear","stay"],"draw_rank":25,"tier_absent_reason":"not-established","source":"https://www.bonafidebonefishing.com/long-island-bahamas-house-rentals","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Flying Fish Marina","blurb":"\"nestled in the protective harbor of Long Island\" on the Atlantic coast, \"an excellent base of operation for sport fishing and diving excursions\". Dockage from $3.25 per foot daily to $2.00 per foot long-term (3-month minimum); a king studio, two double-queen rooms, a king cottage and a one-bedroom apartment. Cape Santa Maria''s guide places it in Clarence Town.","si":["yacht","sailing","ocean"],"commission":"hotel","wells":["activities","stay"],"draw_rank":26,"tier_absent_reason":"not-established","source":"https://www.flyingfishmarina.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Makers Air - Fort Lauderdale to Stella Maris","blurb":"Makers Air lists \"Stella Maris Long Island Flights\" among its scheduled flights from 2331 Northwest 55th Court, Fort Lauderdale; Cape Santa Maria gives the route as FXE to SML \"nonstop three times weekly, on Sundays, Tuesdays, and Thursdays\".","si":["tropical","privatejet"],"commission":"operator","wells":["activities","fly"],"draw_rank":27,"tier_absent_reason":"does-not-compete","source":"https://www.makersair.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Stella Maris Resort Air Service","blurb":"\"routinely operates flights between Nassau and Georgetown, Exuma and Stella Maris, Long Island.\"","si":["tropical","privatejet"],"commission":"operator","wells":["activities","fly","stay"],"draw_rank":28,"tier_absent_reason":"does-not-compete","source":"https://www.stellamarisresort.com/getting-here/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Mutton Fest","blurb":"The Ministry of Tourism names conch and mutton as Long Island''s local specialties and the annual Mutton Fest as their celebration. No dated edition was found on any page read.","si":["culinary","culture"],"wells":["activities","eat"],"draw_rank":29,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/long-island","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — food SI (David 2026-10-05: every traveler has to eat)","commission":"event (free to attend) - pair with Stay-Well and an event-week package","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a festival or regatta - free to attend; the stay and the package around it are the paid route"}],"faq":[{"q":"What is worth doing in Long Island?","a":"Dean''s Blue Hole freedive — the world''s premier freediving arena, a 663-ft sapphire shaft.","source":"https://www.deansbluehole.com/"},{"q":"What is Long Island, Bahamas known for?","a":"The Ministry of Tourism leads with Dean''s Blue Hole, \"the world''s 3rd deepest blue hole\", which hosts the annual international freediving competition. It also names Hamilton''s Cave, \"the largest in The Bahamas, with 50-foot wide passages\", the Columbus Point monument, the twin churches of Clarence Town, Cape Santa Maria Beach, \"world-class\" bonefishing and the Long Island Regatta.","source":"https://www.bahamas.com/islands/long-island","accessed":"2026-10-03"},{"q":"Does Long Island, Bahamas have an airport?","a":"Yes, two: the Ministry of Tourism names Deadman''s Cay Airport (LGI) and Stella Maris Airport (SML).","source":"https://www.bahamas.com/islands/long-island","accessed":"2026-10-03"},{"q":"How do I get to Long Island, Bahamas from Nassau?","a":"By air. Stella Maris Resort lists Bahamasair, which \"Offers daily flights into Stella Maris and Deadman''s Cay from Nassau\", Southern Air, which \"Offers daily flights into Stella Maris from Nassau\", and Stella Maris Resort Air Service, which \"routinely operates flights between Nassau and Georgetown, Exuma and Stella Maris\". This is a hotel''s list, not a carrier timetable.","source":"https://www.stellamarisresort.com/getting-here/","accessed":"2026-10-03"},{"q":"How do I get to Long Island, Bahamas from Florida?","a":"Cape Santa Maria gives Makers Air from Fort Lauderdale Executive Airport (FXE) to Stella Maris Airport (SML), \"nonstop three times weekly, on Sundays, Tuesdays, and Thursdays\". Otherwise it routes through Nassau on Bahamasair or through George Town, Exuma, which has direct flights from Air Canada, American Eagle and Delta, then Island Wings Charters or the Sheep Runner ferry.","source":"https://www.capesantamaria.com/travel-to-long-island-bahamas","accessed":"2026-10-03"},{"q":"How do I get from Exuma to Long Island, Bahamas?","a":"The Sheep Runner ferry runs between George Town, Exuma and Long Island on Mondays, Wednesdays and Fridays, leaving George Town at 3:00 pm and arriving at 4:30 pm. Adult one way is $110, child $71, infants under 2 free, VAT included. \"in inclement weather, the Captain may choose to dock at Harry Cay - a 15 minute car journey south of George Town.\"","source":"https://www.sheeprunner.com/","accessed":"2026-10-03"},{"q":"What is the Sheep Runner ferry to Long Island, Bahamas?","a":"A ferry linking Long Island and George Town, Exuma, about 1.5 hours, Mondays, Wednesdays and Fridays: 7:30 am from Long Island arriving 9:00 am, returning 3:00 pm arriving 4:30 pm. A same-day round trip from Long Island is $165. Booking is online at sheeprunner.com/book-online or on +1 242 472 1030.","source":"https://www.sheeprunner.com/","accessed":"2026-10-03"},{"q":"How do I get around Long Island, Bahamas?","a":"By road. Stella Maris Resort puts Stella Maris Airport \"approximately half-mile from resort\" and Deadman''s Cay Airport a 45-minute drive south, and warns that \"Taxis from Deadman''s Cay need to be prearranged\".","source":"https://www.stellamarisresort.com/getting-here/","accessed":"2026-10-03"},{"q":"Where should I stay on Long Island, Bahamas?","a":"Stella Maris Resort Club & Marina publishes 2026 nightly rates from hotel room apartments ($190-$290) to three- and four-bedroom homes ($660-$800), plus 10% VAT, a 6% resort levy and service and energy charges. In the north, Cape Santa Maria Beach Resort offers beachfront bungalows and villas but \"is closed in September and October\" (capesantamaria.com/long-island-bahamas-resort).","source":"https://www.stellamarisresort.com/rates/","accessed":"2026-10-03"},{"q":"When is the Long Island, Bahamas regatta?","a":"The last dated edition found was June 4-7, 2025, at the Cultural Site in Salt Pond. The Ministry''s trade site calls it \"the second largest in The Bahamas, next to the National Family Island Regatta held in The Exumas\", with A, B and C class sloops racing for cash prizes and trophies. The contact is Mr. Chester Fox, (242) 338-0038 or (242) 357-1292. No 2026 or 2027 date was found.","source":"https://tourismtoday.com/events/long-island-regatta","accessed":"2026-10-03"},{"q":"What restaurants are there on Long Island, Bahamas?","a":"One with its own page is Docky''s Flats Bar, serving \"freshly caught fish, lobster and all the different conch dishes, cooked island style\", open \"on Wednesdays, Fridays and Saturdays after fishing hours\"; \"Please reserve your dinner ahead of time by calling in\" on +1 (242) 357-1417.","source":"https://www.bonafidebonefishing.com/dockys-flats-bar","accessed":"2026-10-03"},{"q":"What is the best time to visit Long Island, Bahamas?","a":"No page read states a best time. NOAA''s National Hurricane Center: \"The Atlantic hurricane season runs from June 1 to November 30\", and \"The peak of the Atlantic hurricane season is September 10, with most activity occurring between mid-August and mid-October.\"","source":"https://www.nhc.noaa.gov/climo/","accessed":"2026-10-03"}],"seo":{"meta_title":"Long Island Bahamas: Dean''s Blue Hole & Freediving","meta_description":"Long Island, Bahamas — home to Dean''s Blue Hole, a world-class freediving mecca, plus Cape Santa Maria beach, reef diving and Out Island calm. When and how.","slug":"long-island-bahamas","primary_keyword":"Dean''s Blue Hole freediving","long_tail":["Long Island Bahamas diving","Cape Santa Maria beach","Vertical Blue freediving","deepest blue hole Bahamas","Stella Maris diving"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-02","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-02","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-08-20T14:54:09Z","source_updated":"2026-05-28T17:01:45+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"expedition","status":"live"},{"si":"diveglobal","status":"live"}],"ultra":null,"source_verified":"2026-07-02","hero":{"query":"Long Island, Bahamas"},"geo":{"lat":23.19,"lng":-75.1},"orbit":[{"id":"abaco-bahamas","jewels":3,"si":["tropical","yacht"]},{"id":"andros-bahamas","jewels":3,"si":["diveglobal"]},{"id":"bimini-bahamas","jewels":3,"si":["diveglobal"]},{"id":"eleuthera-bahamas","jewels":3,"si":["tropical","diveglobal","expedition"]},{"id":"exuma-bahamas","jewels":3,"si":["expedition","liveaboard"]},{"id":"grand-bahama-freeport-bahamas","jewels":3,"si":["diveglobal","liveaboard","expedition"]},{"id":"harbour-island-bahamas","jewels":3,"si":["tropical","ultra","culture"]},{"id":"nassau-paradise-island-bahamas","jewels":3,"si":["romance","diveglobal","liveaboard"]}],"orbit_country":[]}'::jsonb, 51),
